mapper.select:
SELECT tr.orgId, tr.orgName, tr.treatDate, tr.patientId, tr.patientName, tr.mobile, tr.gender, tr.treatType, tr.regDentistId, tr.regDentistName, tr.appointTime, tr.appointDuration, tr.appointContent, tr.regTime, tr.treatStartTime, tr.treatEndTime, tr.treatWaitingTime, tr.treatExpendTime FROM ( SELECT btp.org_id AS orgId, bo.abbreviation AS orgName, DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) AS treatDate, btp.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, bp.gender AS gender, btp.treat_type AS treatType, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName, DATE_FORMAT( btp.appoint_start_time, '%H:%i' ) AS appointTime, btp.appoint_duration AS appointDuration, btp.appoint_content AS appointContent, DATE_FORMAT( btp.registered_time, '%H:%i' ) AS regTime, DATE_FORMAT( btp.treat_start_time, '%H:%i' ) AS treatStartTime, DATE_FORMAT( btp.treat_end_time, '%H:%i' ) AS treatEndTime, TIME_TO_SEC(TIMEDIFF(DATE_FORMAT(btp.treat_start_time,'%H:%i'),DATE_FORMAT(btp.registered_time,'%H:%i')))/60 AS treatWaitingTime, TIME_TO_SEC(TIMEDIFF(DATE_FORMAT(btp.treat_end_time, '%H:%i'), DATE_FORMAT( btp.treat_start_time, '%H:%i' )))/60 AS treatExpendTime FROM base_treatment_process btp LEFT JOIN base_organization bo ON btp.org_id = bo.org_id LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) tr
and tr.orgId = #{query.orgId}
and concat(ifnull(tr.patientName, ''), ifnull(tr.pinyinName, ''), ifnull(tr.mobile, '')) like concat('%', #{query.keyWord}, '%')
and tr.treatType = #{query.treatType}
and tr.treatDate >= #{query.treatStartDate}
and tr.treatDate <= #{query.treatEndDate}
and tr.regDentistId in
#{item}
ORDER BY tr.treatDate DESC

SELECT tmr.treatmentId, tmr.assistant1Id, tmr.assistant1Name, tmr.assistant2Id, tmr.assistant2Name, tmr.assistant3Id, tmr.assistant3Name, tmr.matchingDentistId, tmr.matchingDentistName, tmr.patientId, tmr.patientName, tmr.mobile, tmr.matchingDate, tmr.treatStartTime, tmr.treatEndTime, tmr.matchingDuration FROM ( SELECT btp.org_id as orgId, btp.treatment_id AS treatmentId, btp.assistant_1 AS assistant1Id, be1.employee_name AS assistant1Name, btp.assistant_2 AS assistant2Id, be2.employee_name AS assistant2Name, btp.assistant_3 AS assistant3Id, be3.employee_name AS assistant3Name, btp.registered_dentist_id AS matchingDentistId, be.employee_name AS matchingDentistName, btp.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) AS matchingDate, DATE_FORMAT( btp.treat_start_time, '%H:%i' ) AS treatStartTime, DATE_FORMAT( btp.treat_end_time, '%H:%i' ) AS treatEndTime, TIME_TO_SEC(TIMEDIFF(DATE_FORMAT(btp.treat_end_time, '%H:%i'), DATE_FORMAT( btp.treat_start_time, '%H:%i' )))/60 AS matchingDuration FROM base_treatment_process btp LEFT JOIN base_employee be1 ON btp.assistant_1 = be1.user_id LEFT JOIN base_employee be2 ON btp.assistant_2 = be2.user_id LEFT JOIN base_employee be3 ON btp.assistant_3 = be3.user_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id WHERE btp.treatment_id IS NOT NULL AND ( btp.assistant_1 IS NOT NULL OR btp.assistant_2 IS NOT NULL OR btp.assistant_3 IS NOT NULL ) ) tmr
and tmr.orgId = #{query.orgId}
and concat(ifnull(tmr.patientName, ''), ifnull(tmr.pinyinName, ''), ifnull(tmr.mobile, '')) like concat('%', #{query.keyWord}, '%')
and tmr.matchingDate >= #{query.matchingStartDate}
and tmr.matchingDate <= #{query.matchingEndDate}
and tmr.matchingDentistId in
#{item}
ORDER BY tmr.matchingDate DESC

SELECT btp.treatment_id AS treatmentId, btp.treatDate, btp.patient_id as patientId, btp.patientName, btp.mobile, DATE_FORMAT(btp.treatStartTime, '%Y-%m-%d %H:%i') as treatStartTime, DATE_FORMAT(btp.treatEndTime, '%Y-%m-%d %H:%i') as treatEndTime, btp.matchDuration FROM ( SELECT btp.treatment_id, DATE_FORMAT(btp.treat_start_time, '%Y-%m-%d') as treatDate, btp.patient_id, bp.`name` AS patientName, bp.mobile, bp.pinyin_name AS pinyinName, btp.treat_start_time AS treatStartTime, btp.treat_end_time AS treatEndTime, SUM( btp.matchTime ) AS matchDuration FROM ( SELECT btp.treatment_id, btp.patient_id, btp.assistant_1, btp.treat_start_time, btp.treat_end_time, IF ( TIMESTAMPDIFF( MINUTE, btp.treat_start_time, btp.treat_end_time )=0, 1, TIME_TO_SEC(TIMEDIFF(DATE_FORMAT(btp.treat_end_time, '%H:%i'), DATE_FORMAT( btp.treat_start_time, '%H:%i' )))/60) AS matchTime FROM base_treatment_process btp
and btp.treat_end_time IS NOT NULL
AND btp.org_id = #{query.orgId}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) <= #{query.endDate}
AND btp.assistant_1 = #{query.assistantId}
AND btp.assistant_2 = #{query.assistantId}
AND btp.assistant_3 = #{query.assistantId}
) btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id GROUP BY btp.treatment_id ) btp
and concat(IFNULL(btp.patientName, ''), IFNULL(btp.pinyinName, ''), IFNULL(btp.mobile, '')) like concat('%', #{query.keyword}, '%')
and DATE_FORMAT(btp.treatStartTime,'%Y-%m-%d') >= DATE_FORMAT(#{query.treatStartDate},'%Y-%m-%d')
and DATE_FORMAT(btp.treatStartTime,'%Y-%m-%d') <= DATE_FORMAT(#{query.treatEndDate},'%Y-%m-%d')

select ifnull(count(btp1.appointment_id), 0) as keepAppointmentCount, ifnull(count(btp2.appointment_id), 0) as missAppointmentCount, ifnull(sum(btp3.appoint_modify_time), 0) as changeAppointmentCount, ifnull(count(btp4.appointment_id), 0) as cancelAppointmentCount from base_treatment_process btp left join base_treatment_process btp1 on btp1.appointment_id = btp.appointment_id and btp1.treat_status >=0 left join base_treatment_process btp2 on btp2.appointment_id = btp.appointment_id and btp2.registered_id is null and btp.appoint_status!=2 and date_format(btp2.appoint_start_time, '%Y-%m-%d') < date_format(now(), '%Y-%m-%d') left join base_treatment_process btp3 on btp3.appointment_id = btp.appointment_id left join base_treatment_process btp4 on btp4.appointment_id = btp.appointment_id and btp4.appoint_status = 2
btp.patient_id = #{patientId}
and btp.org_id = #{query.orgId}
and btp.dentist_id = #{query.patientId}
and (date_format(btp.appoint_start_time,'%Y-%m-%d') between date_format(${query.startDate},'%Y-%m-%d') and date_format(${query.endDate},'%Y-%m-%d'))

SELECT IFNULL(btp.origin_type, 0) AS patientOriginTypeId, IFNULL( btp.origin_type_name, '其他' ) AS patientOriginTypeName, COUNT(distinct patient_id ) AS firstTreatCount FROM ( SELECT btp.patient_id, bp.origin_type, bp.origin_type_name FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id
AND btp.treat_type = 0 AND btp.treat_end_time IS NOT NULL
AND btp.org_id = #{query.orgId}
AND DATE_FORMAT( btp.treat_end_time, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_end_time, '%Y-%m' ) <= #{query.endDate}
) btp GROUP BY btp.origin_type, btp.origin_type_name

select
COUNT(distinct patient_id ) AS patientCount
from
base_treatment_process btp

    AND btp.treat_type = 0
    AND btp.treat_end_time IS NOT NULL

        AND btp.org_id = #{query.orgId}


        AND DATE_FORMAT( btp.treat_end_time, '%Y-%m' ) >= #{query.startDate}


        AND DATE_FORMAT( btp.treat_end_time, '%Y-%m' ) <= #{query.endDate}

SELECT distinct btp.registered_dentist_id as registeredDentistId, be.employee_name as registeredDentistName, count(*) as count FROM base_treatment_process btp left join base_employee be on btp.registered_dentist_id = be.user_id
btp.treat_status IN (3, 4) and btp.treat_type = 0
AND btp.org_id = #{orgId}
AND btp.registered_dentist_id in
#{item}
AND be.work_status in
#{item}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{endDate}
GROUP BY btp.registered_dentist_id order by btp.treat_start_time

SELECT
count(*)
FROM
base_treatment_process btp
left join base_employee be on btp.registered_dentist_id = be.user_id

    btp.treat_status IN (3, 4)
    and btp.treat_type = 0

        AND btp.org_id = #{orgId}


        AND btp.registered_dentist_id in

            #{item}



        AND be.work_status in

            #{item}



        AND DATE_FORMAT( btp.treat_end_time, '%Y-%m-%d' ) >= #{startDate}


        AND DATE_FORMAT( btp.treat_end_time, '%Y-%m-%d' ) <= #{endDate}

SELECT distinct bo.abbreviation AS orgName, DATE_FORMAT(btp.treat_start_time, '%Y-%m-%d') AS firstVisitTime, btp.patient_id as patientId, bp.`name` AS patientName, bp.mobile, bp.origin_type_name AS originTypeName,
case when bp.origin_type = 1 then betwo.employee_name when bp.origin_type = 2 then bptwo.name ELSE bpo.`name` END AS originName,
ntp.appoint_content as nextAppointContent, DATE_FORMAT(ntp.appoint_start_time, '%Y-%m-%d') as nextAppointmentTime, vtp.content as nextRemindcontent, DATE_FORMAT(vtp.time, '%Y-%m-%d') as nextRemindTime FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee betwo ON bp.origin_id = betwo.user_id LEFT JOIN base_patient bptwo ON bp.origin_id = bptwo.patient_id LEFT JOIN base_organization bo ON btp.org_id = bo.org_id LEFT JOIN base_patient_origin bpo ON bp.origin_id = bpo.id LEFT JOIN (SELECT DISTINCT patient_id,appoint_content,appoint_start_time FROM base_treatment_process where appoint_start_time > NOW() and appoint_status in (0,1) and (patient_id,appoint_start_time) in( select patient_id,min(appoint_start_time)FROM base_treatment_process where appoint_start_time > NOW() and appoint_status in (0,1) GROUP BY patient_id)) ntp on btp.patient_id = ntp.patient_id LEFT JOIN ( select DISTINCT patient_id,content,time FROM base_visit_remind where time > NOW() and type = 1 and (patient_id,time) in (select patient_id,min(time) FROM base_visit_remind where time > NOW() and type = 1 GROUP BY patient_id)) vtp on btp.patient_id = vtp.patient_id
btp.treat_status IN (3, 4) and btp.treat_type = 0
AND btp.org_id = #{orgId}
AND btp.registered_dentist_id in
#{item}
AND be.work_status in
#{item}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{endDate}
AND concat(IFNULL(bp.`name`,''), IFNULL(bp.medical_number,''), IFNULL(bp.pinyin_name,''), IFNULL(bp.mobile,'')) like concat(concat('%', rtrim(#{patientName})), '%')
order by btp.treat_start_time

SELECT distinct btp.org_id as orgId, btp.registered_dentist_id as registeredDentistId, bo.abbreviation as orgName, be.employee_name as registeredDentistName, count(*) as count FROM base_treatment_process btp left join base_employee be on btp.registered_dentist_id = be.user_id left join base_organization bo on btp.org_id = bo.org_id
btp.treat_status IN (3, 4) and btp.treat_type = 0
AND btp.org_id = #{orgId}
AND btp.registered_dentist_id = #{userId}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{endDate}
GROUP BY btp.registered_dentist_id,btp.org_id order by btp.treat_start_time
